"""cloud.py  --  the AWS calls this lab makes.   >>> YOU DO NOT EDIT THIS FILE <<<

  whoami()          which AWS user your keys belong to (user101 ... user116)
  class_values()    the values for the console form, published by the trainer in S3
  find_runtime()    looks up YOUR Runtime (named askit_<your user>) and its version
  invoke()          calls a Runtime:  invoke_agent_runtime(agentRuntimeArn, runtimeSessionId, payload)
Your keys come from the course .env file (model_factory.py loads it). Region is always us-east-1.
"""
import json
import time
import uuid

REGION = "us-east-1"
CLASS_GW_URL = "https://askit-gw-user116-3zhrfvos7y.gateway.bedrock-agentcore.us-east-1.amazonaws.com/mcp"
BACKUP_ARN = "arn:aws:bedrock-agentcore:us-east-1:868859238853:runtime/askit_askit_agent-8ByhnZDs4E"


def _client(name):
    import boto3
    return boto3.client(name, region_name=REGION)


def new_session_id():
    return "askit-session-" + uuid.uuid4().hex          # 46 characters: AWS needs at least 33


def whoami():
    """-> (user name, account id).  Raises with a plain message if the keys are missing."""
    arn = _client("sts").get_caller_identity()["Arn"]
    return arn.split("/")[-1], arn.split(":")[4]


def class_values(account):
    """The trainer's setup script publishes the console values in S3 (values.json). Falls back to sensible defaults."""
    v = {"bucket": f"dxc-askit-day12-{account}", "key": "askit-agent/askit-agent-v2.zip", "runtime": "PYTHON_3_12",
         "entry": "main.py", "role": "askit-runtime-role", "gateway_url": CLASS_GW_URL, "backup_arn": BACKUP_ARN}
    try:
        body = _client("s3").get_object(Bucket=v["bucket"], Key="askit-agent/values.json")["Body"].read()
        v.update({k: x for k, x in json.loads(body).items() if x})
    except Exception:
        pass
    if isinstance(v.get("entry"), list):
        v["entry"] = " ".join(v["entry"])
    v["s3_uri"] = f"s3://{v['bucket']}/{v['key']}"
    return v


def find_runtime(user):
    """-> dict for YOUR Runtime, or None if you have not created it yet."""
    c = _client("bedrock-agentcore-control")
    want = f"askit_{user}"
    token = None
    while True:
        kw = {"maxResults": 100, **({"nextToken": token} if token else {})}
        page = c.list_agent_runtimes(**kw)
        for r in page.get("agentRuntimes", []):
            if r.get("agentRuntimeName") == want:
                d = c.get_agent_runtime(agentRuntimeId=r["agentRuntimeId"])
                env = d.get("environmentVariables") or {}
                return {"name": want, "id": r["agentRuntimeId"], "arn": d.get("agentRuntimeArn") or r.get("agentRuntimeArn"),
                        "status": d.get("status", r.get("status", "?")), "version": str(d.get("agentRuntimeVersion", r.get("agentRuntimeVersion", "?"))),
                        "gateway_set": bool(env.get("GATEWAY_URL")), "gateway_url": env.get("GATEWAY_URL", ""),
                        "role": (d.get("roleArn") or "").split("/")[-1]}
        token = page.get("nextToken")
        if not token:
            return None


def invoke(arn, prompt, session_id, gateway_url=None):
    """One call to a Runtime. -> dict with ok, answer, steps, ms, session, tools, gateway, error"""
    payload = {"prompt": prompt}
    if gateway_url:
        payload["gateway_url"] = gateway_url
    t0 = time.time()
    try:
        resp = _client("bedrock-agentcore").invoke_agent_runtime(agentRuntimeArn=arn, runtimeSessionId=session_id,
                                                                 payload=json.dumps(payload).encode("utf-8"))
    except Exception as e:                                                    # noqa: BLE001
        return {"ok": False, "ms": int((time.time() - t0) * 1000), "error": explain(e)}
    ms = int((time.time() - t0) * 1000)
    try:
        body = resp.get("response")
        raw = body.read() if hasattr(body, "read") else b"".join(c for c in body)
        text = raw.decode("utf-8", "replace")
        if "text/event-stream" in resp.get("contentType", ""):
            text = "".join(line[6:] for line in text.splitlines() if line.startswith("data: ")) or text
        data = json.loads(text)
    except Exception as e:                                                    # noqa: BLE001
        return {"ok": False, "ms": ms, "error": f"The Runtime answered in a shape this lab does not expect ({type(e).__name__}). Tell the trainer."}
    if isinstance(data, str):
        data = {"answer": data}
    if data.get("error"):
        return {"ok": False, "ms": ms, "error": "The agent in the Runtime said: " + str(data["error"]), "session": data.get("session", {})}
    steps = data.get("steps", [])
    tools = data.get("tools")
    if tools is None:                                                         # older agent code: read the tool list from the steps
        lst = next((s for s in steps if s.get("label") == "tools/list"), None)
        tools = [t.strip() for t in lst["out"].split(",")] if lst else []
    return {"ok": True, "ms": ms, "answer": data.get("answer", ""), "steps": steps, "session": data.get("session", {}), "tools": tools,
            "gateway": data.get("gateway", "sent by the caller" if gateway_url else "?"), "tin": data.get("tokens_in", 0), "tout": data.get("tokens_out", 0),
            "cost": data.get("cost_usd", 0.0)}


def explain(e):
    """Plain-English hint for the errors people meet most."""
    code = ""
    try:
        code = e.response.get("Error", {}).get("Code", "")
    except Exception:
        pass
    hint = {"AccessDeniedException": "Your AWS user may not do this. Tell the trainer: AccessDenied.",
            "ResourceNotFoundException": "Runtime not found. Is it created and Ready in the console?",
            "ThrottlingException": "Too many calls at once. Wait ten seconds and try again.",
            "ValidationException": "AWS did not accept the request. Is your Runtime status Ready?",
            "RuntimeClientError": "The agent code inside the Runtime failed. Check the entry point in the console, or tell the trainer.",
            "NoCredentialsError": "No AWS keys found. Check the .env file in the course folder (C:\\AskIT\\dxc-agentic-ai\\.env)."}.get(code or type(e).__name__, "")
    return f"{code or type(e).__name__}: {str(e)[:240]}  {hint}".strip()
